from taf.sbts.oam.coam.admin.utils import raise_value_error


class WCDMADownlink(object):
    def __init__(self, dist_name, uarfcn, test_model, primary_scrambling_code, number_of_dpch, number_of_hs_pdsch,
                 primary_ccpch_tx_power, dpch_tx_power, dpch_tx_pwr_ctrl_step_size, mimo_phase, mimo_stream,
                 vam_dedicated_test_model):

        self.dist_name = dist_name

        self.uarfcn = self.validate_param('uarfcn',
                                          uarfcn,
                                          (0 <= uarfcn <= 4294967295))

        self.test_model = self.validate_param('testModel',
                                              test_model,
                                              (test_model in (
                                                  "TM_1", "TM_2", "TM_3",
                                                  "TM_4", "TM_5", "TM_6",
                                                  "TM_N7", "TM_N8", "TM_N9",
                                                  "TM_N10", "TM_N11", "TM_N12",
                                                  "TM_N13"
                                              ))
                                              )

        self.primary_scrambling_code = self.validate_param('primaryScramblingCode',
                                                           primary_scrambling_code,
                                                           (0 <= primary_scrambling_code <= 511))

        self.number_of_dpch = self.validate_param('numberOfDpch',
                                                  number_of_dpch,
                                                  (0 <= number_of_dpch <= 64))

        self.number_of_hs_pdsch = self.validate_param('numberOfHsPdsch',
                                                      number_of_hs_pdsch,
                                                      (number_of_hs_pdsch is None or (0 <= number_of_hs_pdsch <= 8)))

        self.primary_ccpch_tx_power = self.validate_param(
            'primaryCcpchTxPower',
            primary_ccpch_tx_power,
            (primary_ccpch_tx_power is None or (-26 <= primary_ccpch_tx_power <= -6)))

        self.dpch_tx_power = self.validate_param('dpchTxPower',
                                                 dpch_tx_power,
                                                 (dpch_tx_power is None or (-28 <= dpch_tx_power <= -3)))

        self.dpch_tx_pwr_ctrl_step_size = self.validate_param(
            'dpchTxPwrCtrlStepSize',
            dpch_tx_pwr_ctrl_step_size,
            (dpch_tx_pwr_ctrl_step_size is None or dpch_tx_pwr_ctrl_step_size in ("0_0", "0_5", "1_0", "1_5", "2_0")))

        self.mimo_phase = self.validate_param('mimoPhase',
                                              mimo_phase,
                                              (mimo_phase is None or mimo_phase in
                                               ("Zero", "One", "Two", "Three", "NoMimo")))

        self.mimo_stream = self.validate_param('mimoStream',
                                               mimo_stream,
                                               (mimo_stream is None or mimo_stream in
                                                ("Single", "Dual")))

        self.vam_dedicated_test_model = self.validate_param('vamDedicatedTestModel',
                                                            vam_dedicated_test_model,
                                                            (vam_dedicated_test_model is None
                                                             or vam_dedicated_test_model in (True, False)))

    @classmethod
    def from_response_dict(cls, response_dict):
        params = response_dict['params']
        dist_name = response_dict['wncel_rDN']
        uarfcn = params['uarfcn']
        test_model = params['testModel']
        primary_scrambling_code = params['primaryScramblingCode']
        number_of_dpch = params['numberOfDpch']
        number_of_hs_pdsch = params['numberOfHsPdsch'] if 'numberOfHsPdsch' in params else None
        primary_ccpch_tx_power = params['primaryCcpchTxPower'] if 'primaryCcpchTxPower' in params else None
        dpch_tx_power = params['dpchTxPower'] if 'dpchTxPower' in params else None
        dpch_tx_pwr_ctrl_step_size = params['dpchTxPwrCtrlStepSize'] if 'dpchTxPwrCtrlStepSize' in params else None
        mimo_phase = params['mimoPhase'] if 'mimoPhase' in params else None
        mimo_stream = params['mimoStream'] if 'mimoStream' in params else None
        vam_dedicated_test_model = params['vamDedicatedTestModel'] if 'vamDedicatedTestModel' in params else None

        return cls(
            dist_name=dist_name,
            uarfcn=uarfcn,
            test_model=test_model,
            primary_scrambling_code=primary_scrambling_code,
            number_of_dpch=number_of_dpch,
            number_of_hs_pdsch=number_of_hs_pdsch,
            primary_ccpch_tx_power=primary_ccpch_tx_power,
            dpch_tx_power=dpch_tx_power,
            dpch_tx_pwr_ctrl_step_size=dpch_tx_pwr_ctrl_step_size,
            mimo_phase=mimo_phase,
            mimo_stream=mimo_stream,
            vam_dedicated_test_model=vam_dedicated_test_model,
        )

    def as_dict(self):
        attributes = {'wncel_rDN': self.dist_name,
                      'params': {'uarfcn': self.uarfcn,
                                 'testModel': self.test_model,
                                 'primaryScramblingCode': self.primary_scrambling_code,
                                 'numberOfDpch': self.number_of_dpch,
                                 'numberOfHsPdsch': self.number_of_hs_pdsch,
                                 'primaryCcpchTxPower': self.primary_ccpch_tx_power,
                                 'dpchTxPower': self.dpch_tx_power,
                                 'dpchTxPwrCtrlStepSize': self.dpch_tx_pwr_ctrl_step_size,
                                 'mimoPhase': self.mimo_phase,
                                 'mimoStream': self.mimo_stream,
                                 'vamDedicatedTestModel': self.vam_dedicated_test_model,
                                 }
                      }

        attributes['params'] = {k: v for k, v in attributes['params'].items() if v is not None}

        return attributes

    @staticmethod
    def validate_param(param, value, valid):
        return value if valid else raise_value_error(
            param=param,
            value=str(value),
            subpage="tutorial-srtStartWcdmaDownlink.html"
        )
